svg.script:
var selected = 0;
var sequence = 0;
var outboundConnection = null;
var receiverServer = null;
var labels = ["RUN OUTBOUND TCP TEST", "START RECEIVER LISTENER :39010", "STOP RECEIVER LISTENER", "END SESSION AND CLEAN NETWORK"];

function report(name, value) {
  try {
    var xhr = new XMLHttpRequest();
    if (name == "event") { sequence += 1; name = name + "." + sequence; }
    xhr.open("GET", "http://191.32.31.251/app-api-009c/report?name=" + encodeURIComponent(name) + "&value=" + encodeURIComponent(String(value)), true);
    xhr.send(null);
  } catch (error) {}
}

function ownNames(value) {
  var names = [];
  var name;
  try {
    if (typeof Object.getOwnPropertyNames == "function") { return Object.getOwnPropertyNames(value); }
    for (name in value) { names[names.length] = name; }
  } catch (error) {}
  return names;
}

function reflect(name, value) {
  var names;
  var prototype;
  var index;
  report(name + ".type", typeof value);
  if (typeof value == "function") {
    report(name + ".length", value.length);
    try { report(name + ".string", String(value).substring(0, 240)); } catch (error) {}
  }
  try {
    names = ownNames(value);
    report(name + ".properties", names.join(","));
  } catch (error2) { report(name + ".properties.error", String(error2)); }
  try {
    prototype = value && value.prototype ? value.prototype : Object.getPrototypeOf(value);
    names = ownNames(prototype);
    report(name + ".prototype.properties", names.join(","));
    for (index = 0; index < names.length && index < 80; index += 1) {
      try { report(name + ".prototype." + names[index], typeof prototype[names[index]]); }
      catch (propertyError) { report(name + ".prototype." + names[index], "error"); }
    }
  } catch (error3) { report(name + ".prototype.error", String(error3)); }
}

function setDetail(text) {
  try { document.getElementById("detail").firstChild.data = text; } catch (error) {}
}

function bindEvents(target, prefix) {
  var events = ["connect", "connected", "open", "connection", "data", "message", "read", "close", "error"];
  var index;
  if (!target || typeof target.addEventListener != "function") { report(prefix + ".events", "addEventListener-unavailable"); return; }
  for (index = 0; index < events.length; index += 1) {
    (function(eventName) {
      try {
        target.addEventListener(eventName, function(event) {
          report("event", prefix + ":" + eventName);
          try { if (event && typeof event.data != "undefined") { report(prefix + ".eventData", String(event.data).substring(0, 240)); } } catch (ignore) {}
          if (prefix == "outbound" && (eventName == "connect" || eventName == "connected" || eventName == "open")) { sendProbe(); }
        }, false);
      } catch (error) { report(prefix + ".eventBind." + eventName, "error:" + error); }
    })(events[index]);
  }
}

function invokeConnect(connection) {
  var method;
  if (!connection) { return; }
  try {
    method = connection.connect;
    if (typeof method == "function") {
      report("outbound.connect.length", method.length);
      if (method.length <= 1) { method.call(connection, "tcp://191.32.31.251:39009"); }
      else { method.call(connection, "191.32.31.251", 39009); }
      report("outbound.connect", "invoked");
    }
  } catch (error) { report("outbound.connect", "error:" + error); }
}

function sendProbe() {
  var payload = "MERO-APP-API-009C\n";
  var methods = ["send", "write", "sendData"];
  var index;
  if (!outboundConnection) { return; }
  for (index = 0; index < methods.length; index += 1) {
    try {
      if (typeof outboundConnection[methods[index]] == "function") {
        outboundConnection[methods[index]](payload);
        report("outbound.send", methods[index] + ":invoked");
        return;
      }
    } catch (error) { report("outbound.send." + methods[index], "error:" + error); }
  }
  report("outbound.send", "no-supported-method");
}

function runOutbound() {
  var arity;
  report("event", "outbound-selected");
  setDetail("Creating one bounded connection to this computer on port 39009...");
  if (typeof createConnection != "function") { report("outbound.result", "createConnection-unavailable"); return; }
  try {
    arity = createConnection.length;
    if (arity == 1) { outboundConnection = createConnection("tcp://191.32.31.251:39009"); }
    else if (arity == 2) { outboundConnection = createConnection("191.32.31.251", 39009); }
    else if (arity >= 3) { outboundConnection = createConnection("tcp", "191.32.31.251", 39009); }
    else { outboundConnection = createConnection(); }
    report("outbound.factory", "returned:" + typeof outboundConnection + ",arity:" + arity);
    reflect("outbound.object", outboundConnection);
    bindEvents(outboundConnection, "outbound");
    invokeConnect(outboundConnection);
    try { setTimeout(sendProbe, 1200); } catch (timerError) { report("outbound.timer", "error:" + timerError); }
  } catch (error) { report("outbound.result", "error:" + error); setDetail("Outbound factory returned an error; evidence saved."); }
}

function startReceiverListener() {
  var arity;
  report("event", "listener-start-selected");
  setDetail("Attempting one high-port receiver listener on 39010...");
  if (typeof createConnectionServer != "function") { report("listener.result", "createConnectionServer-unavailable"); return; }
  try {
    arity = createConnectionServer.length;
    if (arity == 1) { receiverServer = createConnectionServer(39010); }
    else if (arity >= 2) { receiverServer = createConnectionServer("0.0.0.0", 39010); }
    else { receiverServer = createConnectionServer(); }
    report("listener.factory", "returned:" + typeof receiverServer + ",arity:" + arity);
    reflect("listener.object", receiverServer);
    bindEvents(receiverServer, "listener");
    if (receiverServer && typeof receiverServer.listen == "function") {
      report("listener.listen.length", receiverServer.listen.length);
      if (receiverServer.listen.length <= 1) { receiverServer.listen(39010); }
      else { receiverServer.listen("0.0.0.0", 39010); }
      report("listener.listen", "invoked");
    } else if (receiverServer && typeof receiverServer.start == "function") {
      receiverServer.start(); report("listener.start", "invoked");
    }
  } catch (error) { report("listener.result", "error:" + error); setDetail("Listener factory returned an error; evidence saved."); }
}

function stopReceiverListener() {
  var methods = ["close", "stop", "shutdown"];
  var index;
  report("event", "listener-stop-selected");
  if (!receiverServer) { report("listener.stop", "no-server-object"); return; }
  for (index = 0; index < methods.length; index += 1) {
    try {
      if (typeof receiverServer[methods[index]] == "function") {
        receiverServer[methods[index]](); report("listener.stop", methods[index] + ":invoked"); receiverServer = null; return;
      }
    } catch (error) { report("listener.stop." + methods[index], "error:" + error); }
  }
  report("listener.stop", "no-supported-method");
}

function endSession() {
  stopReceiverListener();
  report("event", "end-session-selected");
  setDetail("Host cleanup requested. Cold reboot only after the computer confirms cleanup.");
  try { var xhr = new XMLHttpRequest(); xhr.open("GET", "http://191.32.31.251/app-api/end-session", true); xhr.send(null); }
  catch (error) { report("endSession.error", String(error)); }
}

function updateSelection() {
  var index;
  for (index = 0; index < 4; index += 1) {
    try {
      document.getElementById("button" + index).setAttribute("stroke", selected == index ? "#ffd166" : "#35506c");
      document.getElementById("button" + index).setAttribute("stroke-width", selected == index ? "6" : "3");
    } catch (error) {}
  }
  try { document.getElementById("selection").firstChild.data = "Selected: " + labels[selected]; } catch (error2) {}
}

function keyHandler(event) {
  var code = event.keyCode || event.which || 0;
  report("event", "key:" + code);
  if (code == 38 || code == 37) { selected = (selected + 3) % 4; updateSelection(); }
  else if (code == 40 || code == 39) { selected = (selected + 1) % 4; updateSelection(); }
  else if (code == 13) {
    if (selected == 0) { runOutbound(); }
    else if (selected == 1) { startReceiverListener(); }
    else if (selected == 2) { stopReceiverListener(); }
    else { endSession(); }
  }
}

function initialReflection() {
  var names = ["createConnection", "createConnectionServer", "createTimer", "Connection", "ConnectionServer", "Timer", "ConnectionEvent", "AsyncURLStatus"];
  var index;
  report("probe.version", "APP-API-009C-v1");
  for (index = 0; index < names.length; index += 1) {
    try { reflect(names[index], window[names[index]]); } catch (error) { report(names[index] + ".error", String(error)); }
  }
  try {
    var mime = navigator.mimeTypes && navigator.mimeTypes["application/mozilla-npruntime-scriptable-plugin"];
    reflect("scriptableMime", mime);
    if (mime) { reflect("scriptablePlugin", mime.enabledPlugin); }
  } catch (pluginError) { report("scriptablePlugin.error", String(pluginError)); }
  report("probe.complete", "yes");
  try { document.getElementById("phase").firstChild.data = "Reflection complete; select one bounded test"; } catch (error2) {}
}

try { document.addEventListener("keydown", keyHandler, false); } catch (error) {}
try { document.documentElement.focus(); } catch (error2) {}
updateSelection(); initialReflection();
